using System;using System.Collections.Generic;using System.Reflection;using Delve;using UnityEngine;
public class ConsoleCmdBatchEightGear:ConsoleCmdAbstract {
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static float Stat(string n,PassiveEffects effect){var item=ItemClass.GetItem(n,false);item.Quality=1;item.Stats=new ItemValue.Stat[0];return EffectManager.GetValue(effect,item);}
 public override string[] getCommands(){return new[]{"batch8gear"};}public override string getDescription(){return "Field mat recipes, actual loaded stats, model geometry and queue regression.";}
 public override void Execute(List<string> args,CommandSenderInfo sender){bool w=XUiM_Recipes.WorkstationCrafting;var b=XUiM_Recipes.BackpackCrafting;try{
  checks=0;XUiM_Recipes.WorkstationCrafting=true;XUiM_Recipes.BackpackCrafting=(BackpackCraftingOptions)1;
  var all=CraftingManager.GetAllRecipes();var inventory=XUiM_Recipes.FilterRecipesByWorkstation("",all);var mat=XUiM_Recipes.FilterRecipesByWorkstation("delveFieldCraftingMat",all);int moved=0;
  foreach(var row in DelveBatchFive.Catalog.Rows){Recipe r=null;foreach(var x in all)if(ForestSliceCatalog.Key(x)==row.Key)r=x;Check(r!=null,"Exact variant "+row.Name);if(row.Name=="delveFieldCraftingMat"){Check(inventory.Contains(r),"Mat inventory recipe");continue;}
   Check(!inventory.Contains(r)&&mat.Contains(r),"Mat exclusive "+row.Name);Check(r.craftingToolType==0,"No add-on needed "+row.Name);
   foreach(var x in all)if(x.GetName()==row.Name)Check(x.craftingArea=="delveFieldCraftingMat","Alternate crafting bypass "+row.Name);
   var te=new TileEntityWorkstation((Chunk)null);te.SetDisableModifiedCheck(true);te.Queue=new[]{new RecipeQueueItem{Recipe=r,Multiplier=1,CraftingTimeLeft=0,OneItemCraftTime=1,Quality=1,StartingEntityId=-1}};
   typeof(TileEntityWorkstation).GetMethod("HandleRecipeQueue",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(te,new object[]{2f});int output=0;foreach(var s in te.Output)if(s.itemValue.type==r.itemValueType)output+=s.count;Check(output==1,"Mat queue "+row.Name);moved++;
  }Check(moved==25&&mat.Count==25,"Exactly 25 mat gear recipes");
  foreach(string n in new[]{"meleeWpnBladeT0BoneKnife","meleeToolRepairT0StoneAxe","armorPrimitiveHelmet","armorPrimitiveOutfit","armorPrimitiveGloves","armorPrimitiveBoots","delveWandRune","delveHealingRune","delveHideRepair"}){bool available=false;foreach(var r in inventory)if(r.GetName()==n&&ForestSliceCatalog.Rank(r)<=20)available=true;Check(available,"Portable primitive/supply "+n);}
  string[] cats={"Light","Padded","Medium","Heavy"};int[] ratings={10,11,12,14};
  for(int i=0;i<cats.Length;i++)foreach(string slot in new[]{"Helmet","Outfit","Gloves","Boots"}){string n="armorDelve"+cats[i]+slot;Check(Math.Abs(Stat(n,PassiveEffects.PhysicalDamageResist)-ratings[i])<.01,"Armor rating "+n);Check(Stat(n,PassiveEffects.DegradationMax)==300,"Armor durability "+n);}
  for(int i=0;i<3;i++)foreach(string slot in new[]{"Helmet","Outfit","Gloves","Boots"}){string cat=new[]{"Light","Medium","Heavy"}[i];Check(Math.Abs(Stat("armorDelveForged"+cat+slot,PassiveEffects.PhysicalDamageResist)-(13+i*3))<.01,"Forged progression "+cat);}
  foreach(var pair in new[]{new[]{"delveBoneDagger","meleeWpnBladeT0BoneKnife"},new[]{"delveOakCudgel","meleeWpnClubT0WoodenClub"},new[]{"delveAshSpear","meleeWpnSpearT0StoneSpear"},new[]{"delveLeatherKnuckles","meleeWpnKnucklesT0LeatherKnuckles"}}){float old=Stat(pair[1],PassiveEffects.EntityDamage),now=Stat(pair[0],PassiveEffects.EntityDamage);Check(now>old*1.15f,"Meaningful melee damage "+pair[0]+" "+old+" -> "+now);Check(Stat(pair[0],PassiveEffects.DegradationMax)>Stat(pair[1],PassiveEffects.DegradationMax),"Melee durability "+pair[0]);SdtdConsole.Instance.Output(pair[0]+" damage "+old+" -> "+now);}
  Check(Stat("delveForgedKnuckles",PassiveEffects.EntityDamage)>Stat("delveLeatherKnuckles",PassiveEffects.EntityDamage)*1.15f,"Forged knuckles remain upgrade");
  foreach(string n in new[]{"delveStarterWand","delveStarterStaff","delveStarterTotem","delveMendingTotem"})Check(Stat(n,PassiveEffects.DegradationMax)==300,"Magic durability "+n);
  Check(Stat("delveMendingTotem",PassiveEffects.MagazineSize)==5,"Mending capacity");
  string[] focuses={"delveStarterWand","delveStarterStaff","delveStarterTotem"};float[] damage={19.8f,46.2f,11f};
  for(int i=0;i<focuses.Length;i++){var item=ItemClass.GetItem(focuses[i],false);item.Quality=1;item.Stats=new ItemValue.Stat[0];var attack=item.ItemClass.Actions[0];float actual=(float)typeof(ItemActionAttack).GetMethod("GetDamageEntity",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(attack,new object[]{item,null,0});Check(Math.Abs(actual-damage[i])<.02f,"Native rune damage "+focuses[i]+" actual="+actual);SdtdConsole.Instance.Output(focuses[i]+" rune hit "+actual);}
  var block=Block.GetBlockValue("delveFieldCraftingMat",false).Block;Check(block is BlockWorkstation,"Native workstation");Check(CraftingManager.GetWorkstationData("delveFieldCraftingMat").WorkstationWindow=="workstation_delveFieldCraftingMat","Dedicated mat UI");
  GameObject prefab=null;foreach(var bundle in AssetBundle.GetAllLoadedAssetBundles())if(bundle.name=="fieldmatbatch08.unity3d")prefab=bundle.LoadAsset<GameObject>("delveFieldCraftingMat");Check(prefab!=null,"Native block loader has loaded mat asset");var collider=prefab.GetComponent<BoxCollider>();Check(collider!=null&&collider.size.x<=1&&collider.size.z<=1&&collider.size.y<.1f,"One-metre low mat collider");Check(prefab.GetComponentsInChildren<MeshRenderer>().Length==3,"Three combined woven meshes");
  SdtdConsole.Instance.Output("[Batch08Gear] PASS "+checks+" checks; 25 exclusive mat recipes and native queues; starter/Forged stats; portable essentials; native mat prefab and one-metre geometry.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Batch08Gear] FAIL "+e);}finally{XUiM_Recipes.WorkstationCrafting=w;XUiM_Recipes.BackpackCrafting=b;}}
}
